import random
from fractions import Fraction
from itertools import combinations
from typing import List, Set


def random_bounded_degree_graph(n: int, delta: int, seed: int) -> Set[frozenset]:
    """Random simple graph in which every vertex has degree at most delta."""
    rng = random.Random(seed)
    deg = [0] * n
    edges: Set[frozenset] = set()
    pairs = list(combinations(range(n), 2))
    rng.shuffle(pairs)
    for u, v in pairs:
        if deg[u] < delta and deg[v] < delta:
            edges.add(frozenset((u, v)))
            deg[u] += 1
            deg[v] += 1
    return edges


def independence_number(n: int, edges: Set[frozenset]) -> int:
    def ok(s):
        return all(frozenset((a, b)) not in edges for a, b in combinations(s, 2))
    for size in range(n, 0, -1):
        for s in combinations(range(n), size):
            if ok(s):
                return size
    return 0


def greedy_colors(n: int, edges: Set[frozenset]) -> int:
    adj: List[Set[int]] = [set() for _ in range(n)]
    for e in edges:
        a, b = tuple(e)
        adj[a].add(b)
        adj[b].add(a)
    color = {}
    for v in range(n):
        used = {color[w] for w in adj[v] if w in color}
        c = 0
        while c in used:
            c += 1
        color[v] = c
    return len(set(color.values()))


def main() -> None:
    for trial in range(20):
        n = 9
        delta = random.Random(trial).randint(1, 4)
        edges = random_bounded_degree_graph(n, delta, seed=trial)
        real_delta = 0
        for v in range(n):
            d = sum(1 for e in edges if v in e)
            real_delta = max(real_delta, d)
        cols = greedy_colors(n, edges)
        i_g = Fraction(independence_number(n, edges), n)
        assert cols <= real_delta + 1
        assert i_g >= Fraction(1, real_delta + 1)
        print(f"trial {trial:2d}: Delta={real_delta} greedy={cols} "
              f"i(G)={i_g}  floor 1/(Delta+1)={Fraction(1, real_delta + 1)}")


if __name__ == "__main__":
    main()

